{
  "items": [
    {
      "title": "CROCorp: Corpus of Parliamentary Debates in Croatia (Version 1.1.1)",
      "url_or_doi": "https://doi.org/10.5281/zenodo.6521643",
      "justification": "Official dataset hosted on Zenodo, published May 9, 2022, by Michal Mochtak, Josip Glaurdić, and Christophe Lesschaeve from the University of Luxembourg. This is the latest available version (v1.1.1). The dataset contains a cleaned and preprocessed corpus of parliamentary debates from the Croatian Parliament (Sabor), covering 2003–2020 across five complete parliamentary terms. It includes over 500,000 speeches and accompanying metadata about elected representatives and their political parties."
    },
    {
      "title": "CROCorp: Corpus of Parliamentary Debates in Croatia (Zenodo, All Versions)",
      "url_or_doi": "https://doi.org/10.5281/zenodo.6521372",
      "justification": "Official concept DOI for the CROCorp dataset, providing a persistent reference to the dataset across versions. This is the DOI recommended by the dataset creators for citation. The repository provides access to the Croatian parliamentary debate corpus, associated metadata, and documentation."
    },
    {
      "title": "CROCorp: Corpus of Parliamentary Debates in Croatia (GESIS, Version 1.0.0)",
      "url_or_doi": "https://doi.org/10.7802/2388",
      "justification": "Official dataset record published by GESIS – Leibniz Institute for the Social Sciences in 2022. This is an earlier version of CROCorp, containing parliamentary debate transcripts and metadata covering Croatia from 2003 to 2020. The repository identifies the newer Zenodo release as the most recent version. Access is available with registration under a CC BY 4.0 license."
    },
    {
      "title": "CROCorp: Corpus of Parliamentary Debates in Croatia, v1.1.1 (2003–2020) – University of Luxembourg",
      "url_or_doi": "https://orbilu.uni.lu/handle/10993/58371",
      "justification": "Institutional repository record maintained by the University of Luxembourg, where the dataset authors are affiliated. It documents CROCorp version 1.1.1, identifies its official Zenodo DOI, and provides access to the dataset codebook. This is an authoritative institutional source for verifying the dataset's authorship, coverage, publication details, and documentation."
    }
  ]
}
